import type { CaseSource, TestCase } from '../ai/schemas.js';
import type { CaseState, StoredCase, StoredRun } from '../db/index.js';
import type { PipelineResult } from '../pipeline/run.js';

/** Shown in every export, because every case was written by an AI. */
export const AI_DRAFT_NOTICE =
  'AI draft: needs QA review. Every case was generated by an AI and must be reviewed and ' +
  'edited by a person before it is relied on.';

export interface ExportCase {
  id: string;
  ticket: string;
  flowStep: string;
  title: string;
  type: TestCase['type'];
  priority: TestCase['priority'];
  preconditions: string[];
  steps: string[];
  expected: string;
  sources: CaseSource[];
  assumptions: string[];
  dependsOn: string[];
  covers: string[];
  grounding: TestCase['grounding'];
  /** What QA did with the case. A case that came straight from a pipeline result is "generated". */
  state: CaseState;
}

export interface ExportStep {
  order: number;
  name: string;
  description: string;
  caseIds: string[];
}

export interface ExportPlanItem {
  ticket: string;
  id: string;
  behaviour: string;
  coveredBy: string[];
}

/** Everything an export needs, whether it comes from a saved run or from a pipeline result. */
export interface ExportRun {
  title: string;
  /** What was asked for, for example "ticket SHP-1234". */
  source: string;
  generatedAt?: Date;
  model?: string;
  author?: string;
  steps: ExportStep[];
  cases: ExportCase[];
  warnings: string[];
  plan: ExportPlanItem[];
}

const fromTestCase = (testCase: TestCase, state: CaseState = 'generated'): ExportCase => ({
  id: testCase.id,
  ticket: testCase.ticket,
  flowStep: testCase.flow_step,
  title: testCase.title,
  type: testCase.type,
  priority: testCase.priority,
  preconditions: testCase.preconditions,
  steps: testCase.steps,
  expected: testCase.expected,
  sources: testCase.sources,
  assumptions: testCase.assumptions,
  dependsOn: testCase.depends_on,
  covers: testCase.covers ?? [],
  grounding: testCase.grounding,
  state,
});

export interface AdapterOptions {
  title: string;
  source?: string;
  author?: string;
}

/** An export of a saved run, with what QA edited, added or deleted. */
export function fromStoredRun(run: StoredRun, options: AdapterOptions): ExportRun {
  const cases = run.cases.map((c: StoredCase) => fromTestCase(c, c.state));
  const plan = run.tickets.flatMap((ticket) =>
    (ticket.plan?.items ?? []).map((item) => ({
      ticket: ticket.ticket,
      id: item.id,
      behaviour: item.behaviour,
      coveredBy: cases
        .filter(
          (c) => c.ticket === ticket.ticket && c.covers.includes(item.id) && c.state !== 'deleted',
        )
        .map((c) => c.id),
    })),
  );

  return {
    title: options.title,
    source: options.source ?? `${run.inputMode} ${run.inputValue}`,
    generatedAt: run.createdAt,
    ...(run.model && { model: run.model }),
    ...(options.author && { author: options.author }),
    steps: run.flow.map((step) => ({
      order: step.position + 1,
      name: step.name,
      description: step.description,
      caseIds: step.caseCodes,
    })),
    cases,
    warnings: run.warnings,
    plan,
  };
}

/** An export of a pipeline result that was not saved (for example a file in out/). */
export function fromPipelineResult(
  result: Pick<PipelineResult, 'cases' | 'flow' | 'warnings' | 'tickets'>,
  options: AdapterOptions & { generatedAt?: Date },
): ExportRun {
  const cases = result.cases.map((c) => fromTestCase(c));
  const plan = result.tickets.flatMap((ticket) =>
    (ticket.plan?.items ?? []).map((item) => ({
      ticket: ticket.ticket,
      id: item.id,
      behaviour: item.behaviour,
      coveredBy: cases
        .filter((c) => c.ticket === ticket.ticket && c.covers.includes(item.id))
        .map((c) => c.id),
    })),
  );
  const model = result.tickets.find((t) => t.model)?.model;

  return {
    title: options.title,
    source: options.source ?? 'a pipeline result',
    ...(options.generatedAt && { generatedAt: options.generatedAt }),
    ...(model && { model }),
    ...(options.author && { author: options.author }),
    steps: result.flow.steps.map((step) => ({
      order: step.order,
      name: step.name,
      description: step.description,
      caseIds: step.caseIds,
    })),
    cases,
    warnings: result.warnings,
    plan,
  };
}

export interface FlowGroup {
  step: ExportStep;
  cases: ExportCase[];
}

/**
 * The cases a reader should see, grouped by flow step in flow order. Deleted cases are left out.
 * A case that no step lists goes into a final "Other" group, so nothing silently disappears.
 */
export function groupByFlow(run: ExportRun): FlowGroup[] {
  const live = run.cases.filter((c) => c.state !== 'deleted');
  const byId = new Map(live.map((c) => [c.id, c]));
  const placed = new Set<string>();
  const groups: FlowGroup[] = [];

  for (const step of [...run.steps].sort((a, b) => a.order - b.order)) {
    const cases = step.caseIds.flatMap((id) => {
      const found = byId.get(id);
      if (!found || placed.has(id)) return [];
      placed.add(id);
      return [found];
    });
    if (cases.length > 0) groups.push({ step, cases });
  }

  const rest = live.filter((c) => !placed.has(c.id));
  if (rest.length > 0) {
    groups.push({
      step: {
        order: groups.length + 1,
        name: 'Other',
        description: '',
        caseIds: rest.map((c) => c.id),
      },
      cases: rest,
    });
  }
  return groups;
}

/** What QA did with the run, counted from the cases. */
export interface ExportSummary {
  /** Cases the AI produced. */
  generated: number;
  kept: number;
  edited: number;
  deleted: number;
  added: number;
  /** Cases in the export (not deleted). */
  total: number;
  /** Share of the AI's cases that survived (kept or edited), 0 to 1. */
  keptShare: number;
}

export function summarize(cases: Pick<ExportCase, 'state'>[]): ExportSummary {
  const count = (state: CaseState) => cases.filter((c) => c.state === state).length;
  const kept = count('generated');
  const edited = count('edited');
  const deleted = count('deleted');
  const added = count('added');
  const generated = kept + edited + deleted;
  return {
    generated,
    kept,
    edited,
    deleted,
    added,
    total: kept + edited + added,
    keptShare: generated === 0 ? 0 : (kept + edited) / generated,
  };
}

export const REVIEW_STATUS: Record<CaseState, string> = {
  generated: 'AI draft: needs QA review',
  edited: 'Edited by QA',
  added: 'Added by QA',
  deleted: 'Deleted',
};

